import { Component, FormEvent, StrictMode, useEffect, useRef, useState } from 'react'
import { createRoot } from 'react-dom/client'
import L from 'leaflet'
import monstaLogo from './assets/monsta-logo.png'
import './styles.css'
import 'leaflet/dist/leaflet.css'

type Role = 'VENDOR' | 'ADMIN'
type Vendor = { id: string; vendorId: string; storeName: string; contactName: string; phone: string; address: string; city: string; state: string; zip: string; imageKey?: string; status: string; createdAt: string }
type Order = { id: string; orderNumber: string; vendorId: string; status: string; items: Array<{ product: string; quantity: number }>; totalBottles: number; totalAmount: number; paymentMethod: 'CHECK' | 'CASH'; createdAt: string }
type Product = { name: string; color: string; inventory: number; imageKey?: string }
type InventoryEntry = { id: string; productName: string; previousQuantity: number; quantity: number; delta: number; reason: string; actorType: string; createdAt: string }
const products: Product[] = [{ name: 'Strawberry Lemonade', color: '#e31b18', inventory: 0 }, { name: 'Classic Lemonade', color: '#ffc400', inventory: 0 }, { name: 'Half & Half', color: '#f36b16', inventory: 0 }, { name: 'Alkaline Water', color: '#38bdf8', inventory: 0 }, { name: 'Blueberry Lemonade', color: '#4f46e5', inventory: 0 }, { name: 'Mango Lemonade', color: '#f59e0b', inventory: 0 }, { name: 'Raspberry Lemonade', color: '#be185d', inventory: 0 }, { name: 'Pineapple Lemonade', color: '#facc15', inventory: 0 }]
const mediaUrl = (key?: string) => key ? `/api/media?key=${encodeURIComponent(key)}` : ''
const api = async <T,>(path: string, init?: RequestInit) => { const headers = init?.body instanceof FormData ? { ...(init.headers ?? {}) } : { 'Content-Type': 'application/json', ...(init?.headers ?? {}) }; const response = await fetch(path, { ...init, signal: AbortSignal.timeout(8000), headers }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error ?? 'Something went wrong'); return data as T }
function ProductBottle({ color, imageKey }: { color: string; imageKey?: string }) { return imageKey ? <img className="bottle bottle-image" src={mediaUrl(imageKey)} alt="" /> : <span className="bottle" style={{ '--bottle': color } as React.CSSProperties} aria-hidden="true" /> }

type RouteStop = { vendor: Vendor; orders: Order[]; bottles: number; status: string }
type RouteData = { provider: string; origin: { address: string; latitude: number; longitude: number } | null; stops: Array<{ vendorId: string; storeName: string; address: string; latitude: number; longitude: number; orderIds: string[]; bottles: number; status: string; milesFromPrevious: number; minutesFromPrevious: number }>; geometry: [number, number][]; totalMiles: number; totalMinutes: number; warnings: string[]; generatedAt: string }
type DriverLocation = { driverKey: string; driverLabel: string; latitude: number; longitude: number; accuracyMeters?: number; heading?: number; speedMps?: number; updatedAt: string; stale?: boolean }
const routeOrderStatuses = ['SUBMITTED', 'APPROVED', 'IN_PRODUCTION', 'READY', 'OUT_FOR_DELIVERY']
const routeAddress = (vendor: Vendor) => `${vendor.address}, ${vendor.city}, ${vendor.state} ${vendor.zip}`
const mapsRouteUrl = (stops: RouteStop[]) => { const addresses = stops.map(({ vendor }) => routeAddress(vendor)); if (!addresses.length) return ''; const destination = encodeURIComponent(addresses[addresses.length - 1]); const origin = encodeURIComponent(addresses[0]); const waypoints = addresses.slice(1, -1).map(encodeURIComponent).join('|'); return `https://www.google.com/maps/dir/?api=1&origin=${origin}&destination=${destination}${waypoints ? `&waypoints=${waypoints}` : ''}` }

function LiveRouteMap({ route, locations }: { route: RouteData; locations: DriverLocation[] }) {
  const mapElement = useRef<HTMLDivElement | null>(null); const map = useRef<L.Map | null>(null); const layers = useRef<L.LayerGroup>({} as L.LayerGroup)
  useEffect(() => { if (!mapElement.current || map.current) return; map.current = L.map(mapElement.current, { zoomControl: true, attributionControl: true }); L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { attribution: '&copy; OpenStreetMap contributors', maxZoom: 19 }).addTo(map.current); layers.current = L.layerGroup().addTo(map.current); map.current.setView([40.75, -73.4], 10); return () => { map.current?.remove(); map.current = null } }, [])
  useEffect(() => { if (!map.current || !layers.current || !route.origin) return; layers.current.clearLayers(); const points = route.geometry.map(([longitude, latitude]) => [latitude, longitude] as L.LatLngExpression); if (points.length > 1) L.polyline(points, { color: '#ffc400', weight: 5, opacity: .9 }).addTo(layers.current); const routeBounds: L.LatLngExpression[] = [[route.origin.latitude, route.origin.longitude]]; L.circleMarker([route.origin.latitude, route.origin.longitude], { radius: 9, color: '#fff', weight: 2, fillColor: '#f36b16', fillOpacity: 1 }).bindTooltip('Start · Brentwood Kitchen').addTo(layers.current); route.stops.forEach((stop, index) => { const point: L.LatLngExpression = [stop.latitude, stop.longitude]; routeBounds.push(point); L.circleMarker(point, { radius: 8, color: '#171205', weight: 2, fillColor: '#ffc400', fillOpacity: 1 }).bindTooltip(`${index + 1}. ${stop.storeName}`).addTo(layers.current) }); locations.forEach((location) => { const point: L.LatLngExpression = [location.latitude, location.longitude]; routeBounds.push(point); L.circleMarker(point, { radius: 10, color: '#fff', weight: 3, fillColor: '#e31b18', fillOpacity: 1 }).bindTooltip(`${location.driverLabel}${location.stale ? ' · stale' : ' · live'}`).addTo(layers.current) }); if (routeBounds.length > 1) map.current.fitBounds(L.latLngBounds(routeBounds), { padding: [28, 28] }) }, [route, locations])
  return <div className="live-map" ref={mapElement} aria-label="Live delivery route map" />
}

function RoutePlanner({ stops, route: providedRoute, locations: providedLocations, driverSharing: providedDriverSharing, onMove, onOpenRoute, onToggleDriver }: { stops: RouteStop[]; route?: RouteData | null; locations?: DriverLocation[]; driverSharing?: boolean; onMove: (index: number, direction: -1 | 1) => void; onOpenRoute: () => void; onToggleDriver?: () => void }) {
  const [loadedRoute, setLoadedRoute] = useState<RouteData | null>(providedRoute ?? null); const [loadedLocations, setLoadedLocations] = useState<DriverLocation[]>(providedLocations ?? []); const [loadedDriverSharing, setLoadedDriverSharing] = useState(false); const driverWatch = useRef<number | null>(null); const route = providedRoute ?? loadedRoute; const locations = providedLocations ?? loadedLocations; const driverSharing = providedDriverSharing ?? loadedDriverSharing
  useEffect(() => { if (providedRoute) return; let active = true; const load = async () => { try { const data = await api<RouteData>('/api/admin/route'); if (active) setLoadedRoute(data) } catch { if (active) setLoadedRoute(null) } }; void load(); const interval = window.setInterval(load, 30_000); return () => { active = false; window.clearInterval(interval) } }, [providedRoute])
  useEffect(() => { if (providedLocations) return; const load = async () => { try { const data = await api<{ locations: DriverLocation[] }>('/api/admin/driver-locations'); setLoadedLocations(data.locations) } catch { setLoadedLocations([]) } }; void load(); const interval = window.setInterval(load, 5_000); return () => window.clearInterval(interval) }, [providedLocations])
  const toggleInternalDriver = () => { if (loadedDriverSharing) { if (driverWatch.current !== null) navigator.geolocation.clearWatch(driverWatch.current); driverWatch.current = null; setLoadedDriverSharing(false); void api('/api/admin/driver-locations', { method: 'DELETE' }); return }; if (!navigator.geolocation) return; const send = (position: GeolocationPosition) => { void api('/api/admin/driver-locations', { method: 'POST', body: JSON.stringify({ latitude: position.coords.latitude, longitude: position.coords.longitude, accuracyMeters: position.coords.accuracy, heading: position.coords.heading, speedMps: position.coords.speed, driverLabel: 'Delivery driver' }) }) }; driverWatch.current = navigator.geolocation.watchPosition(send, () => setLoadedDriverSharing(false), { enableHighAccuracy: true, maximumAge: 5_000, timeout: 15_000 }); setLoadedDriverSharing(true) }
  useEffect(() => () => { if (driverWatch.current !== null) navigator.geolocation.clearWatch(driverWatch.current) }, [])
  const toggleDriver = onToggleDriver ?? toggleInternalDriver; const totalBottles = stops.reduce((sum, stop) => sum + stop.bottles, 0)
  return <section className="route-planner"><div className="route-summary"><div><small>Stops</small><strong>{route?.stops.length ?? stops.length}</strong></div><div><small>Bottles</small><strong>{route ? route.stops.reduce((sum, stop) => sum + stop.bottles, 0) : totalBottles}</strong></div><div><small>Driving distance</small><strong>{route ? `${route.totalMiles} mi` : '—'}</strong><span>{route ? `${route.totalMinutes} min estimated` : 'Calculating route…'}</span></div><button className="primary-action route-action" type="button" onClick={onOpenRoute} disabled={!stops.length}>Open route in Maps</button></div><div className="route-live-toolbar"><span>{route ? `Calculated by ${route.provider}` : 'Loading real road route…'}</span><button className={driverSharing ? 'small-button tracking-active' : 'small-button'} type="button" onClick={onToggleDriver}>{driverSharing ? 'Stop GPS sharing' : 'Start driver GPS'}</button><span>{locations.length} live driver{locations.length === 1 ? '' : 's'}</span></div><div className="route-layout"><section className="admin-card route-stops-card"><div className="section-heading"><div><p className="eyebrow">Driving sequence</p><h2>Ready drop-offs</h2></div><span>Optimized by road distance</span></div>{route?.warnings.map((warning) => <p className="route-warning" key={warning}>{warning}</p>)}{route?.stops.length ? route.stops.map((stop, index) => <article className="route-stop" key={stop.vendorId}><div className="stop-number">{index + 1}</div><div className="stop-details"><strong>{stop.storeName}</strong><small>{stop.address}</small><span>{stop.bottles} bottles · {stop.milesFromPrevious} mi · {stop.minutesFromPrevious} min · {stop.status.replaceAll('_', ' ')}</span></div></article>) : stops.length ? stops.map((stop, index) => <article className="route-stop" key={stop.vendor.id}><div className="stop-number">{index + 1}</div><div className="stop-details"><strong>{stop.vendor.storeName}</strong><small>{routeAddress(stop.vendor)}</small><span>{stop.bottles ? `${stop.bottles} bottles · ` : ''}{stop.status.replaceAll('_', ' ')}</span></div><div className="stop-controls"><button type="button" aria-label={`Move ${stop.vendor.storeName} up`} disabled={index === 0} onClick={() => onMove(index, -1)}>↑</button><button type="button" aria-label={`Move ${stop.vendor.storeName} down`} disabled={index === stops.length - 1} onClick={() => onMove(index, 1)}>↓</button></div></article>) : <p className="muted">No ready or out-for-delivery orders are waiting for a route.</p>}</section><section className="admin-card route-map-card"><div className="section-heading"><div><p className="eyebrow">Live road map</p><h2>Driver and route</h2></div><span>GPS updates every 5 seconds</span></div>{route?.origin ? <LiveRouteMap route={route} locations={locations} /> : <div className="route-map-loading">{route ? 'No ready delivery stops to map.' : 'Preparing route coordinates…'}</div>}<div className="route-map-legend"><span><i className="legend-start" /> Start</span><span><i className="legend-stop" /> Stop</span><span><i className="legend-driver" /> Driver</span></div><p className="muted">Red markers show active driver phones. A stale marker means that phone has not checked in for 30 seconds.</p></section></div></section>
}

function Gate({ onLogin }: { onLogin: (role: Role) => Promise<void> }) {
  const [pin, setPin] = useState(''); const [message, setMessage] = useState('Authorized retailers only. Your PIN identifies your vendor account.'); const [busy, setBusy] = useState(false)
  async function submit(event: FormEvent) { event.preventDefault(); if (!/^\d{4,6}$/.test(pin)) { setMessage('Enter your four-digit vendor PIN or six-digit admin PIN.'); return }; setBusy(true); try { const data = await api<{ role: Role }>('/api/auth/login', { method: 'POST', body: JSON.stringify({ pin }) }); await onLogin(data.role) } catch (error) { setMessage(error instanceof Error ? error.message : 'Invalid credentials.') } finally { setBusy(false) } }
  return <main className="gate-shell"><section className="gate-card" aria-labelledby="page-title"><div className="hero-art"><img className="hero-logo" src={monstaLogo} alt="Monsta Squeeze" /></div><p className="eyebrow">Monsta Squeeze / Retail portal</p><h1 id="page-title">Retail restock</h1><p className="lede">Private access for authorized Monsta Squeeze retailers.</p><form className="pin-form" onSubmit={submit}><label htmlFor="vendor-pin">Vendor PIN</label><input id="vendor-pin" inputMode="numeric" autoComplete="off" maxLength={6} placeholder="Enter your PIN" value={pin} onChange={(event) => setPin(event.target.value.replace(/\D/g, ''))} /><button type="submit" disabled={busy}>{busy ? 'Checking…' : 'Access restock'}</button></form><p className="setup-note" role="status">{message}</p></section></main>
}

function VendorPortal({ vendor, onLogout }: { vendor: Vendor; onLogout: () => void }) {
  const [catalog, setCatalog] = useState<Product[]>(products); const [quantities, setQuantities] = useState(products.map(() => 0)); const [paymentMethod, setPaymentMethod] = useState<'CHECK' | 'CASH'>('CHECK'); const [orders, setOrders] = useState<Order[]>([]); const [message, setMessage] = useState(''); const total = quantities.reduce((sum, quantity) => sum + quantity, 0)
  useEffect(() => { Promise.all([api<{ products: Product[] }>('/api/catalog'), api<{ orders: Order[] }>('/api/orders')]).then(([catalogData, orderData]) => { setCatalog(catalogData.products); setQuantities(catalogData.products.map(() => 0)); setOrders(orderData.orders) }).catch(() => setMessage('Could not load your product catalog.')) }, [])
  const adjust = (index: number, amount: number) => setQuantities((current) => current.map((quantity, item) => item === index ? Math.max(0, quantity + amount) : quantity))
  async function submitOrder() { try { const data = await api<{ order: Order }>('/api/orders', { method: 'POST', body: JSON.stringify({ paymentMethod, items: catalog.map((product, index) => ({ product: product.name, quantity: quantities[index] })) }) }); setOrders((current) => [data.order, ...current]); setMessage(`${data.order.orderNumber} submitted successfully.`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Order could not be submitted.') } }
  return <div className="portal"><header className="topbar"><img className="brand-logo" src={monstaLogo} alt="Monsta Squeeze" /><button className="text-button" onClick={onLogout}>Log out</button></header><main className="vendor-main"><section className="welcome hero-panel">{vendor.imageKey && <img className="vendor-hero-image" src={mediaUrl(vendor.imageKey)} alt={`${vendor.storeName} storefront`} />}<div className="vendor-hero-copy"><p className="eyebrow">Welcome back,</p><h1>{vendor.storeName}</h1><p>{vendor.vendorId}<br />{vendor.address}<br />{vendor.city}, {vendor.state} {vendor.zip}</p></div></section><section className="info-card"><div className="section-heading"><span>Account contact</span><small>{vendor.contactName}</small></div><strong>{vendor.phone}</strong><div className="mini-breakdown">Authorized retailer <i /> Active account</div></section><section className="workflow-card" id="restock-builder"><div className="step-label">01 / Build restock order</div><h2>Build your restock</h2><p className="muted">Select how many bottles you need. Minimum order: 24 bottles.</p>{catalog.map((product, index) => <div className="quantity-row" key={product.name}><ProductBottle color={product.color} imageKey={product.imageKey} /><div><strong>{product.name}</strong><small>$4.00 each</small></div><button type="button" onClick={() => adjust(index, -1)} aria-label={`Decrease ${product.name}`}>−</button><b>{quantities[index]}</b><button type="button" onClick={() => adjust(index, 1)} aria-label={`Increase ${product.name}`}>+</button></div>)}<div className="totals"><span>Total bottles <b>{total}</b></span><span>Wholesale total <b>${(total * 4).toFixed(2)}</b></span></div><fieldset><legend>Payment method</legend><label><input type="radio" name="payment" checked={paymentMethod === 'CHECK'} onChange={() => setPaymentMethod('CHECK')} /> Check</label><label><input type="radio" name="payment" checked={paymentMethod === 'CASH'} onChange={() => setPaymentMethod('CASH')} /> Cash</label></fieldset><button className="primary-action" type="button" disabled={total < 24} onClick={submitOrder}>Submit restock</button><p className="setup-note" role="status">{message}</p></section><section className="history-card"><div className="section-heading"><h2>Order history</h2><span>{orders.length} orders</span></div>{orders.length ? orders.map((order) => <div className="history-row" key={order.id}><div><strong>{order.orderNumber}</strong><small>{new Date(order.createdAt).toLocaleDateString()} &nbsp; {order.totalBottles} bottles</small></div><span className="status submitted">{order.status}</span><b>${order.totalAmount.toFixed(2)}</b></div>) : <p className="muted">Your submitted orders will appear here.</p>}</section></main></div>
}

function AdminOperations({ vendors, orders, onOrders }: { vendors: Vendor[]; orders: Order[]; onOrders: (orders: Order[]) => void }) {
  const [tab, setTab] = useState('production'); const [message, setMessage] = useState('')
  const setStatus = async (order: Order, status: string) => { try { const data = await api<{ order: Order }>('/api/admin/orders', { method: 'PATCH', body: JSON.stringify({ orderId: order.id, status }) }); onOrders(orders.map((entry) => entry.id === order.id ? data.order : entry)); setMessage(`${order.orderNumber} moved to ${status}.`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not update order.') } }
  const totalBottles = orders.reduce((sum, order) => sum + Number(order.totalBottles || 0), 0); const totalValue = orders.reduce((sum, order) => sum + Number(order.totalAmount || 0), 0)
  return <section className="admin-operations"><div className="admin-tabs">{['production', 'inventory', 'route', 'payments', 'analytics'].map((item) => <button className={tab === item ? 'active' : ''} key={item} onClick={() => setTab(item)}>{item.replace(/^./, (letter) => letter.toUpperCase())}</button>)}</div>{tab === 'production' && <section className="admin-card"><div className="section-heading"><h2>Production queue</h2><span>Live orders</span></div>{orders.length ? orders.map((order) => <div className="route-row" key={order.id}><span>{order.orderNumber}<small>{order.items.map((item) => `${item.quantity} ${item.product}`).join(' · ')}</small></span><b>{order.totalBottles}</b><select value={order.status} onChange={(event) => setStatus(order, event.target.value)}><option>SUBMITTED</option><option>APPROVED</option><option>IN_PRODUCTION</option><option>READY</option><option>OUT_FOR_DELIVERY</option><option>DELIVERED</option><option>CLOSED</option></select><em>{order.status}</em></div>) : <p className="muted">No production orders yet.</p>}</section>}{tab === 'inventory' && <section className="admin-card"><div className="section-heading"><h2>Inventory ledger</h2><span>Interim Blobs mode</span></div>{products.map((product) => <div className="inventory-row" key={product.name}><span className="inventory-icon">◆</span>{product.name}<b>{Math.max(0, 500 - orders.reduce((sum, order) => sum + (order.items.find((item) => item.product === product.name)?.quantity ?? 0), 0))}</b></div>)}<p className="muted">Temporary counts until the Supabase inventory ledger is connected.</p></section>}{tab === 'route' && <section className="admin-card"><div className="section-heading"><h2>Route / delivery</h2><span>Ready orders</span></div>{orders.filter((order) => ['READY', 'OUT_FOR_DELIVERY'].includes(order.status)).map((order) => <div className="route-row" key={order.id}><span>{vendors.find((vendor) => vendor.id === order.vendorId)?.storeName ?? 'Vendor'}<small>{order.orderNumber}</small></span><b>{order.totalBottles}</b><span>{order.status}</span><em>Route</em></div>)}{!orders.some((order) => ['READY', 'OUT_FOR_DELIVERY'].includes(order.status)) && <p className="muted">No ready deliveries.</p>}</section>}{tab === 'payments' && <section className="admin-card"><div className="section-heading"><h2>Payments</h2><span>Expected wholesale</span></div>{orders.map((order) => <div className="route-row" key={order.id}><span>{order.orderNumber}<small>{order.paymentMethod}</small></span><b>${order.totalAmount.toFixed(2)}</b><span>EXPECTED</span><em>Open</em></div>)}{!orders.length && <p className="muted">No payments expected.</p>}</section>}{tab === 'analytics' && <section className="admin-card"><div className="section-heading"><h2>Analytics</h2><span>Current stored data</span></div><div className="analytics-grid"><div><small>Total orders</small><strong>{orders.length}</strong></div><div><small>Bottles ordered</small><strong>{totalBottles}</strong></div><div><small>Wholesale value</small><strong>${totalValue.toFixed(2)}</strong></div><div><small>Active vendors</small><strong>{vendors.filter((vendor) => vendor.status === 'ACTIVE').length}</strong></div></div><p className="muted">Calculated from stored portal orders and compatible with the future Supabase reporting layer.</p></section>}<p className="setup-note" role="status">{message}</p></section>
}

class AdminRenderBoundary extends Component<{ children: React.ReactNode }, { failed: boolean }> {
  state = { failed: false }
  static getDerivedStateFromError() { return { failed: true } }
  render() { return this.state.failed ? <section className="admin-card recovery-card"><p className="eyebrow">Operations control</p><h2>Dashboard data needs attention</h2><p className="muted">The admin session is active, but one dashboard panel could not render. The operations tools below remain available.</p></section> : this.props.children }
}

function AdminPortalLegacy({ onLogout }: { onLogout: () => void }) {
  const [vendors, setVendors] = useState<Vendor[]>([]); const [orders, setOrders] = useState<Order[]>([]); const [message, setMessage] = useState(''); const [form, setForm] = useState({ storeName: '', contactName: '', phone: '', address: '', city: '', state: '', zip: '', pin: '' });
  const load = () => Promise.all([api<{ vendors: Vendor[] }>('/api/admin/vendors'), api<{ orders: Order[] }>('/api/orders')]).then(([vendorData, orderData]) => { setVendors(vendorData.vendors); setOrders(orderData.orders) }).catch(() => setMessage('Could not load operations data.'))
  useEffect(() => { load() }, [])
  async function createVendor(event: FormEvent) { event.preventDefault(); try { const data = await api<{ issuedPin: string; vendor: Vendor }>('/api/admin/vendors', { method: 'POST', body: JSON.stringify(form) }); setVendors((current) => [...current, data.vendor]); setForm({ storeName: '', contactName: '', phone: '', address: '', city: '', state: '', zip: '', pin: '' }); setMessage(`${data.vendor.storeName} created. Vendor PIN: ${data.issuedPin}`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Vendor could not be created.') } }
  const update = (key: keyof typeof form) => (event: React.ChangeEvent<HTMLInputElement>) => setForm((current) => ({ ...current, [key]: event.target.value }))
  return <div className="admin-layout"><aside className="admin-nav"><img className="brand-logo" src={monstaLogo} alt="Monsta Squeeze" /><button className="active">▦ <span>Dashboard</span></button><button onClick={() => document.getElementById('vendor-accounts')?.scrollIntoView({ behavior: 'smooth' })}>♙ <span>Vendor accounts</span></button><button onClick={() => document.getElementById('admin-orders')?.scrollIntoView({ behavior: 'smooth' })}>▤ <span>Orders</span></button><button onClick={onLogout}>↪ <span>Log out</span></button></aside><main className="admin-main"><header className="admin-header"><div><p className="eyebrow">Operations control</p><h1>Dashboard</h1><p className="muted">Manage retailers, PIN access, and submitted restock orders.</p></div><button className="text-button" onClick={onLogout}>Admin · Log out</button></header><div className="metric-grid"><div className="metric-card"><span>♧</span><small>Active vendors</small><strong>{vendors.filter((vendor) => vendor.status === 'ACTIVE').length}</strong></div><div className="metric-card"><span>▣</span><small>Open orders</small><strong>{orders.filter((order) => order.status === 'SUBMITTED').length}</strong></div><div className="metric-card"><span>◉</span><small>Bottles ordered</small><strong>{orders.reduce((sum, order) => sum + order.totalBottles, 0)}</strong></div><div className="metric-card"><span>$</span><small>Wholesale value</small><strong>${orders.reduce((sum, order) => sum + order.totalAmount, 0).toFixed(0)}</strong></div></div><section className="admin-card" id="vendor-accounts"><div className="section-heading"><h2>Create vendor account</h2><span>Issue a PIN</span></div><form className="admin-vendor-form" onSubmit={createVendor}>{(['storeName', 'contactName', 'phone', 'address', 'city', 'state', 'zip', 'pin'] as const).map((key) => <label key={key}>{key === 'storeName' ? 'Store name' : key === 'contactName' ? 'Contact name' : key === 'pin' ? 'PIN (optional 4 digits)' : key.replace(/([A-Z])/g, ' $1')}<input required={key !== 'pin'} inputMode={key === 'pin' || key === 'zip' ? 'numeric' : undefined} maxLength={key === 'pin' ? 4 : undefined} value={form[key]} onChange={update(key)} /></label>)}<button className="primary-action" type="submit">Create account + issue PIN</button></form><p className="setup-note" role="status">{message}</p></section><section className="admin-card"><div className="section-heading"><h2>Vendor accounts</h2><span>{vendors.length} total</span></div>{vendors.map((vendor) => <div className="route-row" key={vendor.id}><span>{vendor.storeName}<small>{vendor.vendorId} · {vendor.contactName}</small></span><b>{vendor.city}</b><span>{vendor.status}</span><em>Active</em></div>)}</section><section className="admin-card route-card" id="admin-orders"><div className="section-heading"><h2>Submitted orders</h2><span>{orders.length} total</span></div>{orders.map((order) => <div className="route-row" key={order.id}><span>{order.orderNumber}<small>{vendors.find((vendor) => vendor.id === order.vendorId)?.storeName ?? 'Vendor'}</small></span><b>{order.totalBottles}</b><span>${order.totalAmount.toFixed(2)}</span><em>{order.status}</em></div>)}{!orders.length && <p className="muted">No orders submitted yet.</p>}</section></main></div>
}

function AdminPortalMedia({ onLogout }: { onLogout: () => void }) {
  const [route, setRoute] = useState<RouteData | null>(null); const [driverLocations, setDriverLocations] = useState<DriverLocation[]>([]); const [driverSharing, setDriverSharing] = useState(false); const driverWatch = useRef<number | null>(null)
  const [vendors, setVendors] = useState<Vendor[]>([]); const [orders, setOrders] = useState<Order[]>([]); const [catalog, setCatalog] = useState<Product[]>(products); const [inventoryHistory, setInventoryHistory] = useState<InventoryEntry[]>([]); const [tab, setTab] = useState<'dashboard' | 'vendors' | 'inventory' | 'orders' | 'route' | 'analytics'>('dashboard'); const [message, setMessage] = useState(''); const [routeStops, setRouteStops] = useState<RouteStop[]>([]); const [form, setForm] = useState({ storeName: '', contactName: '', phone: '', address: '', city: '', state: '', zip: '', pin: '' }); const [vendorImage, setVendorImage] = useState<File | null>(null)
  useEffect(() => { Promise.all([api<{ vendors: Vendor[] }>('/api/admin/vendors'), api<{ orders: Order[] }>('/api/orders'), api<{ products: Product[]; inventoryHistory: InventoryEntry[] }>('/api/admin/catalog')]).then(([vendorData, orderData, catalogData]) => { const nextVendors = vendorData.vendors ?? []; const nextOrders = orderData.orders ?? []; setVendors(nextVendors); setOrders(nextOrders); setCatalog(catalogData.products); setInventoryHistory(catalogData.inventoryHistory ?? []); setRouteStops(nextVendors.filter((vendor) => vendor.status === 'ACTIVE').map((vendor) => { const vendorOrders = nextOrders.filter((order) => order.vendorId === vendor.id && routeOrderStatuses.includes(order.status)); return { vendor, orders: vendorOrders, bottles: vendorOrders.reduce((sum, order) => sum + Number(order.totalBottles || 0), 0), status: vendorOrders[0]?.status ?? 'NO ACTIVE ORDER' } })) }).catch((error) => setMessage(error instanceof Error ? error.message : 'Could not load admin data.')) }, [])
  const bottles = orders.reduce((sum, order) => sum + Number(order.totalBottles || 0), 0); const value = orders.reduce((sum, order) => sum + Number(order.totalAmount || 0), 0); const openOrders = orders.filter((order) => !['CLOSED', 'DELIVERED'].includes(order.status)); const update = (key: keyof typeof form) => (event: React.ChangeEvent<HTMLInputElement>) => setForm((current) => ({ ...current, [key]: event.target.value })); const nav = (next: typeof tab, label: string, icon: string) => <button className={tab === next ? 'active' : ''} onClick={() => setTab(next)}>{icon} <span>{label}</span></button>
  async function uploadMedia(scope: 'vendor' | 'product', id: string, file: File) { const body = new FormData(); body.set('scope', scope); body.set('id', id); body.set('file', file); return api<{ imageKey: string }>('/api/admin/media', { method: 'POST', body }) }
  async function createVendor(event: FormEvent) { event.preventDefault(); try { const data = await api<{ issuedPin: string; vendor: Vendor }>('/api/admin/vendors', { method: 'POST', body: JSON.stringify(form) }); let vendor = data.vendor; if (vendorImage) vendor = { ...vendor, imageKey: (await uploadMedia('vendor', vendor.id, vendorImage)).imageKey }; setVendors((current) => [...current, vendor]); setRouteStops((current) => [...current, { vendor, orders: [], bottles: 0, status: 'NO ACTIVE ORDER' }]); setForm({ storeName: '', contactName: '', phone: '', address: '', city: '', state: '', zip: '', pin: '' }); setVendorImage(null); setMessage(`${vendor.storeName} created. Vendor PIN: ${data.issuedPin}`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Vendor could not be created.') } }
  async function saveVendorImage(vendor: Vendor, file: File) { try { const imageKey = (await uploadMedia('vendor', vendor.id, file)).imageKey; setVendors((current) => current.map((entry) => entry.id === vendor.id ? { ...entry, imageKey } : entry)); setRouteStops((current) => current.map((stop) => stop.vendor.id === vendor.id ? { ...stop, vendor: { ...stop.vendor, imageKey } } : stop)); setMessage(`${vendor.storeName} image saved.`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Vendor image could not be saved.') } }
  async function saveProductImage(product: Product, file: File) { try { const imageKey = (await uploadMedia('product', product.name, file)).imageKey; setCatalog((current) => current.map((entry) => entry.name === product.name ? { ...entry, imageKey } : entry)); setMessage(`${product.name} image saved.`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Product image could not be saved.') } }
  async function saveInventory(product: Product, inventory: string) { try { const data = await api<{ product: Product; inventoryEntry: InventoryEntry }>('/api/admin/catalog', { method: 'PATCH', body: JSON.stringify({ name: product.name, inventory: Number(inventory), reason: 'MANUAL_COUNT' }) }); setCatalog((current) => current.map((entry) => entry.name === product.name ? data.product : entry)); setInventoryHistory((current) => [data.inventoryEntry, ...current].filter(Boolean)) } catch (error) { setMessage(error instanceof Error ? error.message : 'Inventory could not be saved.') } }
  const moveStop = (index: number, direction: -1 | 1) => setRouteStops((current) => { const next = [...current]; const target = index + direction; if (target < 0 || target >= next.length) return current; [next[index], next[target]] = [next[target], next[index]]; return next }); const openRoute = () => { const stops = route?.stops ?? routeStops.map((stop) => ({ vendorId: stop.vendor.id, storeName: stop.vendor.storeName, address: routeAddress(stop.vendor), latitude: 0, longitude: 0, orderIds: stop.orders.map((order) => order.id), bottles: stop.bottles, status: stop.status, milesFromPrevious: 0, minutesFromPrevious: 0 })); const addresses = stops.map((stop) => stop.address); if (addresses.length) window.open(`https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(route?.origin?.address ?? '1509 Brentwood Rd, Brentwood, NY')}&destination=${encodeURIComponent(addresses[addresses.length - 1])}&waypoints=${addresses.slice(0, -1).map(encodeURIComponent).join('|')}`, '_blank', 'noopener,noreferrer') }
  const toggleDriverSharing = () => { if (driverSharing) { if (driverWatch.current !== null) navigator.geolocation.clearWatch(driverWatch.current); driverWatch.current = null; setDriverSharing(false); void api('/api/admin/driver-locations', { method: 'DELETE' }); return }; if (!navigator.geolocation) { setMessage('This phone does not provide GPS location.'); return }; const handlePosition = (position: GeolocationPosition) => { void api('/api/admin/driver-locations', { method: 'POST', body: JSON.stringify({ latitude: position.coords.latitude, longitude: position.coords.longitude, accuracyMeters: position.coords.accuracy, heading: position.coords.heading, speedMps: position.coords.speed, driverLabel: 'Delivery driver' }) }).catch(() => setMessage('GPS update could not be sent.')) }; const handleError = () => setMessage('GPS permission is required to share the driver location.'); driverWatch.current = navigator.geolocation.watchPosition(handlePosition, handleError, { enableHighAccuracy: true, maximumAge: 5_000, timeout: 15_000 }); setDriverSharing(true) }
  useEffect(() => () => { if (driverWatch.current !== null) navigator.geolocation.clearWatch(driverWatch.current) }, [])
  return <div className="admin-layout"><aside className="admin-nav"><img className="brand-logo" src={monstaLogo} alt="Monsta Squeeze" />{nav('dashboard', 'Dashboard', '▦')}{nav('vendors', 'Vendor accounts', '♙')}{nav('inventory', 'Inventory', '◈')}{nav('orders', 'Orders', '▤')}{nav('route', 'Route / Delivery', '⌁')}{nav('analytics', 'Analytics', '◌')}<button onClick={onLogout}>↪ <span>Log out</span></button></aside><main className="admin-main"><header className="admin-header"><div><p className="eyebrow">Operations control</p><h1>{tab === 'dashboard' ? 'Dashboard' : tab === 'vendors' ? 'Vendor accounts' : tab === 'inventory' ? 'Inventory & product images' : tab === 'orders' ? 'Orders' : tab === 'route' ? 'Route / Delivery' : 'Analytics'}</h1><p className="muted">Manage retailers, PIN access, products, inventory, and delivery readiness.</p></div><button className="text-button" onClick={onLogout}>Admin · Log out</button></header>{tab === 'dashboard' && <><div className="metric-grid"><div className="metric-card"><span>♧</span><small>Active vendors</small><strong>{vendors.length}</strong></div><div className="metric-card"><span>▣</span><small>Open orders</small><strong>{openOrders.length}</strong></div><div className="metric-card"><span>◉</span><small>Bottles ordered</small><strong>{bottles}</strong></div><div className="metric-card"><span>$</span><small>Wholesale value</small><strong>${value.toFixed(0)}</strong></div></div><div className="dashboard-grid"><section className="admin-card"><div className="section-heading"><h2>Needs attention</h2><button className="small-button" onClick={() => setTab('orders')}>View all</button></div>{openOrders.slice(0, 4).map((order) => <div className="attention-row" key={order.id}><span className="attention-icon">$</span><div><strong>{order.orderNumber}</strong><small>{order.status.replaceAll('_', ' ')} · {order.totalBottles} bottles</small></div><em>{order.status}</em></div>)}{!openOrders.length && <p className="muted">No open orders need attention.</p>}</section><section className="admin-card"><div className="section-heading"><h2>Inventory snapshot</h2><button className="small-button" onClick={() => setTab('inventory')}>Manage</button></div>{catalog.slice(0, 4).map((product) => <div className="production-row" key={product.name}><ProductBottle color={product.color} imageKey={product.imageKey} /><span>{product.name}</span><b>{product.inventory}</b></div>)}</section><section className="admin-card dashboard-route-card"><div className="section-heading"><h2>Delivery route</h2><button className="small-button" onClick={() => setTab('route')}>View route</button></div><div className="route-progress"><strong>{routeStops.filter((stop) => stop.orders.some((order) => ['READY', 'OUT_FOR_DELIVERY'].includes(order.status))).length} of {routeStops.length}</strong><span>stops have ready orders</span></div><p className="muted">Manual stop order with live Maps routing.</p></section><section className="admin-card dashboard-orders-card"><div className="section-heading"><h2>Recent orders</h2><button className="small-button" onClick={() => setTab('orders')}>View all</button></div>{orders.slice(0, 5).map((order) => <div className="route-row" key={order.id}><span>{order.orderNumber}<small>{order.totalBottles} bottles</small></span><b>${Number(order.totalAmount || 0).toFixed(2)}</b><em>{order.status}</em></div>)}{!orders.length && <p className="muted">No submitted orders yet.</p>}</section></div></>}{tab === 'vendors' && <section className="admin-card"><div className="section-heading"><h2>Create vendor account</h2><span>Issue a PIN</span></div><form className="admin-vendor-form" onSubmit={createVendor}>{(['storeName', 'contactName', 'phone', 'address', 'city', 'state', 'zip', 'pin'] as const).map((key) => <label key={key}>{key === 'storeName' ? 'Store name' : key === 'contactName' ? 'Contact name' : key === 'pin' ? 'PIN (optional 4 digits)' : key.replace(/([A-Z])/g, ' $1')}<input required={key !== 'pin'} inputMode={key === 'pin' || key === 'zip' ? 'numeric' : undefined} maxLength={key === 'pin' ? 4 : undefined} value={form[key]} onChange={update(key)} /></label>)}<label className="upload-field">Store image (optional)<input type="file" accept="image/*" onChange={(event) => setVendorImage(event.target.files?.[0] ?? null)} /></label><button className="primary-action" type="submit">Create account + issue PIN</button></form><p className="setup-note" role="status">{message}</p><div className="section-heading"><h2>Existing vendors</h2><span>{vendors.length}</span></div>{vendors.map((vendor) => <div className="vendor-admin-row" key={vendor.id}><span>{vendor.storeName}<small>{vendor.vendorId} · {vendor.contactName}</small></span><label className="file-button">{vendor.imageKey ? 'Replace image' : 'Add image'}<input type="file" accept="image/*" onChange={(event) => { const file = event.target.files?.[0]; if (file) void saveVendorImage(vendor, file) }} /></label><em>{vendor.status}</em></div>)}</section>}{tab === 'inventory' && <><section className="admin-card"><div className="section-heading"><div><p className="eyebrow">Catalog control</p><h2>Inventory and bottle images</h2></div><span>{catalog.length} flavors</span></div><p className="muted">Set the current on-hand count. Every change saves the previous count, new count, adjustment, reason, and exact timestamp.</p>{catalog.map((product) => <div className="catalog-admin-row" key={product.name}><ProductBottle color={product.color} imageKey={product.imageKey} /><div><strong>{product.name}</strong><small>{product.imageKey ? 'Image uploaded' : 'Using color placeholder'}</small></div><label>On hand<input type="number" min="0" value={product.inventory} onChange={(event) => setCatalog((current) => current.map((entry) => entry.name === product.name ? { ...entry, inventory: Number(event.target.value) } : entry))} onBlur={(event) => void saveInventory(product, event.currentTarget.value)} /></label><label className="file-button">{product.imageKey ? 'Replace' : 'Upload'}<input type="file" accept="image/*" onChange={(event) => { const file = event.target.files?.[0]; if (file) void saveProductImage(product, file) }} /></label></div>)}</section><section className="admin-card inventory-history-card"><div className="section-heading"><div><p className="eyebrow">Audit trail</p><h2>Inventory updates</h2></div><span>{inventoryHistory.length} recorded</span></div>{inventoryHistory.length ? inventoryHistory.slice(0, 25).map((entry) => <div className="inventory-history-row" key={entry.id}><span><strong>{entry.productName}</strong><small>{new Date(entry.createdAt).toLocaleString()} · {entry.reason}</small></span><b>{entry.previousQuantity} → {entry.quantity}</b><em>{entry.delta > 0 ? `+${entry.delta}` : entry.delta}</em></div>) : <p className="muted">No inventory updates have been recorded yet.</p>}</section></>}{tab === 'orders' && <section className="admin-card"><div className="section-heading"><h2>Submitted orders</h2><span>{orders.length}</span></div>{orders.map((order) => <div className="route-row" key={order.id}><span>{order.orderNumber}<small>{vendors.find((vendor) => vendor.id === order.vendorId)?.storeName ?? 'Vendor'}</small></span><b>{order.totalBottles}</b><span>${Number(order.totalAmount || 0).toFixed(2)}</span><em>{order.status}</em></div>)}{!orders.length && <p className="muted">No orders submitted yet.</p>}</section>}{tab === 'route' && <RoutePlanner stops={routeStops} onMove={moveStop} onOpenRoute={openRoute} />}{tab === 'analytics' && <section className="admin-card"><div className="section-heading"><h2>Analytics</h2><span>Stored portal data</span></div><div className="analytics-grid"><div><small>Total orders</small><strong>{orders.length}</strong></div><div><small>Bottles ordered</small><strong>{bottles}</strong></div><div><small>Wholesale value</small><strong>${value.toFixed(2)}</strong></div><div><small>Active vendors</small><strong>{vendors.length}</strong></div></div><p className="muted">Calculated from the interim Netlify Blobs data layer.</p></section>}</main></div>
}

function VendorManager({ onClose }: { onClose: () => void }) {
  const [vendors, setVendors] = useState<Vendor[]>([]); const [selected, setSelected] = useState<Vendor | null>(null); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false)
  useEffect(() => { api<{ vendors: Vendor[] }>('/api/admin/vendors').then((data) => setVendors(data.vendors ?? [])).catch(() => setMessage('Could not load vendor accounts.')) }, [])
  const save = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!selected) return; setBusy(true); try { const data = await api<{ vendor: Vendor }>('/api/admin/vendors', { method: 'PATCH', body: JSON.stringify(selected) }); setVendors((current) => current.map((vendor) => vendor.id === data.vendor.id ? data.vendor : vendor)); setSelected(data.vendor); setMessage('Vendor details saved.') } catch (error) { setMessage(error instanceof Error ? error.message : 'Vendor could not be updated.') } finally { setBusy(false) } }
  const setField = (field: keyof Vendor, value: string) => setSelected((current) => current ? { ...current, [field]: value } : current)
  const hide = async (vendor: Vendor) => { setBusy(true); try { const data = await api<{ vendor: Vendor }>('/api/admin/vendors', { method: 'PATCH', body: JSON.stringify({ vendorId: vendor.id, status: vendor.status === 'SUSPENDED' ? 'ACTIVE' : 'SUSPENDED' }) }); setVendors((current) => current.map((entry) => entry.id === data.vendor.id ? data.vendor : entry)); setSelected(data.vendor); setMessage(data.vendor.status === 'SUSPENDED' ? 'Vendor hidden from login and active routes.' : 'Vendor reactivated.') } catch { setMessage('Vendor status could not be changed.') } finally { setBusy(false) } }
  const remove = async (vendor: Vendor) => { if (!window.confirm(`Delete ${vendor.storeName}? Accounts with order history will be closed instead.`)) return; setBusy(true); try { const data = await api<{ vendor?: Vendor; vendorId: string; deleted: boolean; closed?: boolean }>('/api/admin/vendors', { method: 'DELETE', body: JSON.stringify({ vendorId: vendor.id }) }); if (data.deleted) { setVendors((current) => current.filter((entry) => entry.id !== data.vendorId)); setSelected(null); setMessage('Vendor deleted.') } else if (data.vendor) { setVendors((current) => current.map((entry) => entry.id === data.vendor?.id ? data.vendor! : entry)); setSelected(data.vendor); setMessage('Vendor has order history, so it was closed instead of deleted.') } } catch (error) { setMessage(error instanceof Error ? error.message : 'Vendor could not be deleted.') } finally { setBusy(false) } }
  return <section className="vendor-manager-overlay" role="dialog" aria-modal="true" aria-labelledby="vendor-manager-title"><div className="vendor-manager-card"><div className="section-heading"><div><p className="eyebrow">Account controls</p><h2 id="vendor-manager-title">Edit vendor accounts</h2></div><button className="small-button" type="button" onClick={onClose}>Close</button></div><p className="muted">Edit store information, hide an account with Suspend, or delete accounts without order history.</p><div className="vendor-manager-list">{vendors.map((vendor) => <article className={`vendor-manager-row ${vendor.status !== 'ACTIVE' ? 'is-hidden' : ''}`} key={vendor.id}><div><strong>{vendor.storeName}</strong><small>{vendor.vendorId} · {vendor.status}</small></div><div className="vendor-manager-actions"><button className="small-button" type="button" onClick={() => setSelected(vendor)}>Edit</button><button className="small-button" type="button" onClick={() => void hide(vendor)} disabled={busy}>{vendor.status === 'SUSPENDED' ? 'Show' : 'Hide'}</button><button className="danger-button" type="button" onClick={() => void remove(vendor)} disabled={busy}>Delete</button></div></article>)}</div>{selected && <form className="vendor-edit-form" onSubmit={save}><div className="section-heading"><h3>Edit {selected.storeName}</h3><button className="small-button" type="button" onClick={() => setSelected(null)}>Cancel</button></div>{(['storeName', 'contactName', 'phone', 'address', 'city', 'state', 'zip'] as const).map((field) => <label key={field}>{field.replace(/([A-Z])/g, ' $1')}<input required value={selected[field]} onChange={(event) => setField(field, event.target.value)} /></label>)}<label>Status<select value={selected.status} onChange={(event) => setField('status', event.target.value)}><option value="ACTIVE">Active</option><option value="SUSPENDED">Hidden / suspended</option><option value="CLOSED">Closed</option></select></label><button className="primary-action" type="submit" disabled={busy}>{busy ? 'Saving…' : 'Save vendor changes'}</button></form>}<p className="setup-note" role="status">{message}</p></div></section>
}

function App() { const [role, setRole] = useState<Role | null>(null); const [vendorManagerOpen, setVendorManagerOpen] = useState(false); const [vendor, setVendor] = useState<Vendor | null>(null); const [loading, setLoading] = useState(true); const [transitioning, setTransitioning] = useState(false); const [error, setError] = useState(''); useEffect(() => { api<{ role: Role; vendor?: Vendor }>('/api/session').then((data) => { setRole(data.role); setVendor(data.vendor ?? null) }).catch(() => {}).finally(() => setLoading(false)) }, []); const logout = async () => { await fetch('/api/auth/logout', { method: 'POST' }); setRole(null); setVendor(null); setError('') }; const login = async (next: Role) => { setTransitioning(true); setError(''); try { if (next === 'VENDOR') { const data = await api<{ vendor: Vendor }>('/api/session'); if (!data.vendor) throw new Error('Vendor account could not be loaded.'); setVendor(data.vendor) }; setRole(next) } catch (loginError) { setRole(null); setVendor(null); setError(loginError instanceof Error ? loginError.message : 'Secure portal could not be loaded.') } finally { setTransitioning(false) } }; if (loading || transitioning) return <main className="gate-shell"><p className="eyebrow">Loading secure portal…</p></main>; if (error) return <main className="gate-shell"><section className="gate-card recovery-card"><p className="eyebrow">Secure portal</p><h1>We could not open your portal.</h1><p className="lede">{error}</p><button className="primary-action" onClick={() => setError('')}>Return to login</button></section></main>; if (role === 'ADMIN') return <><AdminPortalMedia onLogout={logout} /><button className="vendor-manager-launch" type="button" onClick={() => setVendorManagerOpen(true)}>Manage vendor accounts</button>{vendorManagerOpen && <VendorManager onClose={() => setVendorManagerOpen(false)} />}</>; if (role === 'VENDOR' && vendor) return <VendorPortal vendor={vendor} onLogout={logout} />; return <Gate onLogin={login} /> }
function AdminPortalLegacyShell({ onLogout }: { onLogout: () => void }) { const [vendors, setVendors] = useState<Vendor[]>([]); const [orders, setOrders] = useState<Order[]>([]); useEffect(() => { Promise.all([api<{ vendors: Vendor[] }>('/api/admin/vendors'), api<{ orders: Order[] }>('/api/orders')]).then(([vendorData, orderData]) => { setVendors(vendorData.vendors); setOrders(orderData.orders) }).catch(() => {}) }, []); return <><AdminRenderBoundary><AdminPortalLegacy onLogout={onLogout} /></AdminRenderBoundary><AdminOperations vendors={vendors} orders={orders} onOrders={setOrders} /></> }

function SafeOperations({ onLogout }: { onLogout: () => void }) { const [tab, setTab] = useState<'route' | 'analytics'>('route'); const [orders, setOrders] = useState<Order[]>([]); const [vendors, setVendors] = useState<Vendor[]>([]); useEffect(() => { Promise.all([api<{ orders: Order[] }>('/api/orders'), api<{ vendors: Vendor[] }>('/api/admin/vendors')]).then(([orderData, vendorData]) => { setOrders(Array.isArray(orderData.orders) ? orderData.orders : []); setVendors(Array.isArray(vendorData.vendors) ? vendorData.vendors : []) }).catch(() => {}) }, []); const bottles = orders.reduce((sum, order) => sum + Number(order.totalBottles || 0), 0); const value = orders.reduce((sum, order) => sum + Number(order.totalAmount || 0), 0); return <main className="safe-admin"><div className="safe-admin-bar"><button onClick={() => setTab('route')} className={tab === 'route' ? 'active' : ''}>Route / Delivery</button><button onClick={() => setTab('analytics')} className={tab === 'analytics' ? 'active' : ''}>Analytics</button><button onClick={onLogout}>Log out</button></div>{tab === 'route' ? <section className="admin-card"><div className="section-heading"><h2>Route / delivery</h2><span>{orders.length} orders</span></div>{orders.filter((order) => ['READY', 'OUT_FOR_DELIVERY'].includes(order.status)).map((order) => <div className="route-row" key={order.id}><span>{vendors.find((vendor) => vendor.id === order.vendorId)?.storeName ?? 'Vendor'}<small>{order.orderNumber}</small></span><b>{order.totalBottles}</b><span>{order.status}</span><em>Route</em></div>)}{!orders.some((order) => ['READY', 'OUT_FOR_DELIVERY'].includes(order.status)) && <p className="muted">No ready deliveries yet.</p>}</section> : <section className="admin-card"><div className="section-heading"><h2>Analytics</h2><span>Stored portal data</span></div><div className="analytics-grid"><div><small>Total orders</small><strong>{orders.length}</strong></div><div><small>Bottles ordered</small><strong>{bottles}</strong></div><div><small>Wholesale value</small><strong>${value.toFixed(2)}</strong></div><div><small>Active vendors</small><strong>{vendors.length}</strong></div></div><p className="muted">Calculated from the interim Netlify Blobs data layer.</p></section>}</main> }
function AdminPortalBrokenShell({ onLogout }: { onLogout: () => void }) { return <><AdminPortalLegacyShell onLogout={onLogout} /><SafeOperations onLogout={onLogout} /></> }

function AdminPortalOld({ onLogout }: { onLogout: () => void }) { return <><AdminRenderBoundary><AdminPortalLegacy onLogout={onLogout} /></AdminRenderBoundary><SafeOperations onLogout={onLogout} /></> }

function AdminPortalEnhanced({ onLogout }: { onLogout: () => void }) {
  const [vendors, setVendors] = useState<Vendor[]>([]); const [orders, setOrders] = useState<Order[]>([]); const [catalog, setCatalog] = useState<Product[]>(products); const [message, setMessage] = useState(''); const [tab, setTab] = useState<'dashboard' | 'vendors' | 'inventory' | 'orders' | 'route' | 'analytics'>('dashboard'); const [routeStops, setRouteStops] = useState<RouteStop[]>([]); const [route, setRoute] = useState<RouteData | null>(null); const [driverLocations, setDriverLocations] = useState<DriverLocation[]>([]); const [driverSharing, setDriverSharing] = useState(false); const driverWatch = useRef<number | null>(null); const [vendorImage, setVendorImage] = useState<File | null>(null); const [form, setForm] = useState({ storeName: '', contactName: '', phone: '', address: '', city: '', state: '', zip: '', pin: '' })
  useEffect(() => { Promise.all([api<{ vendors: Vendor[] }>('/api/admin/vendors'), api<{ orders: Order[] }>('/api/orders'), api<{ products: Product[] }>('/api/admin/catalog')]).then(([vendorData, orderData, catalogData]) => { const nextVendors = Array.isArray(vendorData.vendors) ? vendorData.vendors : []; const nextOrders = Array.isArray(orderData.orders) ? orderData.orders : []; setVendors(nextVendors); setOrders(nextOrders); setCatalog(catalogData.products); setRouteStops(nextVendors.filter((vendor) => vendor.status === 'ACTIVE').map((vendor) => { const vendorOrders = nextOrders.filter((order) => order.vendorId === vendor.id && routeOrderStatuses.includes(order.status)); return { vendor, orders: vendorOrders, bottles: vendorOrders.reduce((sum, order) => sum + Number(order.totalBottles || 0), 0), status: vendorOrders[0]?.status ?? 'NO ACTIVE ORDER' } })) }).catch((error) => setMessage(error instanceof Error ? error.message : 'Could not load admin data.')) }, [])
  useEffect(() => { if (tab !== 'route') return; let cancelled = false; const loadRoute = async () => { try { const data = await api<RouteData>('/api/admin/route'); if (!cancelled) { setRoute(data); setRouteStops(data.stops.map((stop) => { const vendor = vendors.find((entry) => entry.id === stop.vendorId); const stopOrders = orders.filter((order) => stop.orderIds.includes(order.id)); return vendor ? { vendor, orders: stopOrders, bottles: stop.bottles, status: stop.status } : null }).filter((stop): stop is RouteStop => Boolean(stop))) } } catch (error) { if (!cancelled) setMessage(error instanceof Error ? error.message : 'Could not calculate the road route.') } }; void loadRoute(); const interval = window.setInterval(loadRoute, 30_000); return () => { cancelled = true; window.clearInterval(interval) } }, [tab, vendors, orders])
  useEffect(() => { if (tab !== 'route') return; const loadLocations = async () => { try { const data = await api<{ locations: DriverLocation[] }>('/api/admin/driver-locations'); setDriverLocations(data.locations) } catch { setDriverLocations([]) } }; void loadLocations(); const interval = window.setInterval(loadLocations, 5_000); return () => window.clearInterval(interval) }, [tab])
  const update = (key: keyof typeof form) => (event: React.ChangeEvent<HTMLInputElement>) => setForm((current) => ({ ...current, [key]: event.target.value })); const bottles = orders.reduce((sum, order) => sum + Number(order.totalBottles || 0), 0); const value = orders.reduce((sum, order) => sum + Number(order.totalAmount || 0), 0); const openOrders = orders.filter((order) => !['CLOSED', 'DELIVERED'].includes(order.status)); const productionItems = catalog.map((product) => ({ ...product, quantity: orders.reduce((sum, order) => sum + Number(order.items.find((item) => item.product === product.name)?.quantity || 0), 0) })).filter((product) => product.quantity > 0)
  async function uploadMedia(scope: 'vendor' | 'product', id: string, file: File) { const body = new FormData(); body.set('scope', scope); body.set('id', id); body.set('file', file); return api<{ imageKey: string }>('/api/admin/media', { method: 'POST', body, headers: {} }) }
  async function uploadProductImage(product: Product, file: File) { try { const data = await uploadMedia('product', product.name, file); setCatalog((current) => current.map((entry) => entry.name === product.name ? { ...entry, imageKey: data.imageKey } : entry)); setMessage(`${product.name} image saved.`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Product image could not be saved.') } }
  async function updateInventory(product: Product, inventory: string) { const data = await api<{ product: Product }>('/api/admin/catalog', { method: 'PATCH', body: JSON.stringify({ name: product.name, inventory: Number(inventory) }) }); setCatalog((current) => current.map((entry) => entry.name === product.name ? data.product : entry)) }
  async function uploadVendorImage(vendor: Vendor, file: File) { try { const data = await uploadMedia('vendor', vendor.id, file); setVendors((current) => current.map((entry) => entry.id === vendor.id ? { ...entry, imageKey: data.imageKey } : entry)); setRouteStops((current) => current.map((stop) => stop.vendor.id === vendor.id ? { ...stop, vendor: { ...stop.vendor, imageKey: data.imageKey } } : stop)); setMessage(`${vendor.storeName} image saved.`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Vendor image could not be saved.') } }
  async function createVendor(event: FormEvent) { event.preventDefault(); try { const data = await api<{ issuedPin: string; vendor: Vendor }>('/api/admin/vendors', { method: 'POST', body: JSON.stringify(form) }); let savedVendor = data.vendor; if (vendorImage) { const media = await uploadMedia('vendor', data.vendor.id, vendorImage); savedVendor = { ...data.vendor, imageKey: media.imageKey } }; setVendors((current) => [...current, savedVendor]); setRouteStops((current) => [...current, { vendor: savedVendor, orders: [], bottles: 0, status: 'NO ACTIVE ORDER' }]); setForm({ storeName: '', contactName: '', phone: '', address: '', city: '', state: '', zip: '', pin: '' }); setVendorImage(null); setMessage(`${data.vendor.storeName} created. Vendor PIN: ${data.issuedPin}`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Vendor could not be created.') } }
  const moveStop = (index: number, direction: -1 | 1) => setRouteStops((current) => { const next = [...current]; const target = index + direction; if (target < 0 || target >= next.length) return current; [next[index], next[target]] = [next[target], next[index]]; return next }); const openRoute = () => { const url = mapsRouteUrl(routeStops.filter((stop) => stop.orders.length)); if (url) window.open(url, '_blank', 'noopener,noreferrer') }
  const nav = (next: typeof tab, label: string, icon: string) => <button className={tab === next ? 'active' : ''} onClick={() => setTab(next)}>{icon} <span>{label}</span></button>
  return <div className="admin-layout"><aside className="admin-nav"><img className="brand-logo" src={monstaLogo} alt="Monsta Squeeze" />{nav('dashboard', 'Dashboard', '▦')}{nav('vendors', 'Vendor accounts', '♙')}{nav('orders', 'Orders', '▤')}{nav('route', 'Route / Delivery', '⌁')}{nav('analytics', 'Analytics', '◌')}<button onClick={onLogout}>↪ <span>Log out</span></button></aside><main className="admin-main"><header className="admin-header"><div><p className="eyebrow">Operations control</p><h1>{tab === 'dashboard' ? 'Dashboard' : tab === 'vendors' ? 'Vendor accounts' : tab === 'orders' ? 'Orders' : tab === 'route' ? 'Route / Delivery' : 'Analytics'}</h1><p className="muted">Manage retailers, PIN access, orders, and delivery readiness.</p></div><button className="text-button" onClick={onLogout}>Admin · Log out</button></header>{tab === 'dashboard' && <><div className="metric-grid"><div className="metric-card"><span>♧</span><small>Active vendors</small><strong>{vendors.filter((vendor) => vendor.status === 'ACTIVE').length}</strong><em className="metric-note">Retail accounts</em></div><div className="metric-card"><span>▣</span><small>Open orders</small><strong>{openOrders.length}</strong><em className="metric-note">Needs attention</em></div><div className="metric-card"><span>◉</span><small>Bottles ordered</small><strong>{bottles}</strong><em className="metric-note">Current stored data</em></div><div className="metric-card"><span>$</span><small>Wholesale value</small><strong>${value.toFixed(0)}</strong><em className="metric-note">Submitted orders</em></div></div><div className="dashboard-grid"><section className="admin-card"><div className="section-heading"><h2>Needs attention</h2><button className="small-button" onClick={() => setTab('orders')}>View all</button></div>{openOrders.slice(0, 4).map((order) => <div className="attention-row" key={order.id}><span className="attention-icon">{order.status === 'SUBMITTED' ? '$' : '✓'}</span><div><strong>{order.orderNumber}</strong><small>{order.status.replaceAll('_', ' ')} · {order.totalBottles} bottles</small></div><em>{order.status}</em></div>)}{!openOrders.length && <p className="muted">No open orders need attention.</p>}</section><section className="admin-card"><div className="section-heading"><h2>Production required</h2><button className="small-button" onClick={() => setTab('orders')}>View details</button></div>{productionItems.slice(0, 5).map((item) => <div className="production-row" key={item.name}><ProductBottle color={item.color} /><span>{item.name}</span><b>{item.quantity} bottles</b></div>)}{!productionItems.length && <p className="muted">No product demand is stored yet.</p>}</section><section className="admin-card dashboard-route-card"><div className="section-heading"><h2>Delivery route</h2><button className="small-button" onClick={() => setTab('route')}>View route</button></div><div className="route-progress"><strong>{routeStops.filter((stop) => stop.orders.some((order) => ['READY', 'OUT_FOR_DELIVERY'].includes(order.status))).length} of {routeStops.length}</strong><span>stops have ready orders</span></div><p className="muted">Route order is available for manual planning; live mileage opens in Maps.</p></section><section className="admin-card dashboard-orders-card"><div className="section-heading"><h2>Recent orders</h2><button className="small-button" onClick={() => setTab('orders')}>View all</button></div>{orders.slice(0, 5).map((order) => <div className="route-row" key={order.id}><span>{order.orderNumber}<small>{order.totalBottles} bottles</small></span><b>${Number(order.totalAmount || 0).toFixed(2)}</b><em>{order.status}</em></div>)}{!orders.length && <p className="muted">No submitted orders yet.</p>}</section></div></>}{tab === 'vendors' && <section className="admin-card"><div className="section-heading"><h2>Create vendor account</h2><span>Issue a PIN</span></div><form className="admin-vendor-form" onSubmit={createVendor}>{(['storeName', 'contactName', 'phone', 'address', 'city', 'state', 'zip', 'pin'] as const).map((key) => <label key={key}>{key === 'storeName' ? 'Store name' : key === 'contactName' ? 'Contact name' : key === 'pin' ? 'PIN (optional 4 digits)' : key.replace(/([A-Z])/g, ' $1')}<input required={key !== 'pin'} inputMode={key === 'pin' || key === 'zip' ? 'numeric' : undefined} maxLength={key === 'pin' ? 4 : undefined} value={form[key]} onChange={update(key)} /></label>)}<button className="primary-action" type="submit">Create account + issue PIN</button></form><p className="setup-note" role="status">{message}</p><div className="section-heading"><h2>Existing vendors</h2><span>{vendors.length}</span></div>{vendors.map((vendor) => <div className="route-row" key={vendor.id}><span>{vendor.storeName}<small>{vendor.vendorId} · {vendor.contactName}</small></span><b>{vendor.city}</b><em>{vendor.status}</em></div>)}</section>}{tab === 'orders' && <section className="admin-card"><div className="section-heading"><h2>Submitted orders</h2><span>{orders.length}</span></div>{orders.map((order) => <div className="route-row" key={order.id}><span>{order.orderNumber}<small>{vendors.find((vendor) => vendor.id === order.vendorId)?.storeName ?? 'Vendor'}</small></span><b>{order.totalBottles}</b><span>${Number(order.totalAmount || 0).toFixed(2)}</span><em>{order.status}</em></div>)}{!orders.length && <p className="muted">No orders submitted yet.</p>}</section>}{tab === 'route' && <><RoutePlanner stops={routeStops} onMove={moveStop} onOpenRoute={openRoute} /><p className="setup-note" role="status">{message}</p></>}{tab === 'analytics' && <section className="admin-card"><div className="section-heading"><h2>Analytics</h2><span>Stored portal data</span></div><div className="analytics-grid"><div><small>Total orders</small><strong>{orders.length}</strong></div><div><small>Bottles ordered</small><strong>{bottles}</strong></div><div><small>Wholesale value</small><strong>${value.toFixed(2)}</strong></div><div><small>Active vendors</small><strong>{vendors.length}</strong></div></div><p className="muted">Calculated from the interim Netlify Blobs data layer.</p></section>}</main></div>
}

function AdminPortal({ onLogout }: { onLogout: () => void }) { const [vendors, setVendors] = useState<Vendor[]>([]); const [orders, setOrders] = useState<Order[]>([]); const [message, setMessage] = useState(''); const [tab, setTab] = useState<'dashboard' | 'vendors' | 'orders' | 'route' | 'analytics'>('dashboard'); const [form, setForm] = useState({ storeName: '', contactName: '', phone: '', address: '', city: '', state: '', zip: '', pin: '' }); useEffect(() => { Promise.all([api<{ vendors: Vendor[] }>('/api/admin/vendors'), api<{ orders: Order[] }>('/api/orders')]).then(([vendorData, orderData]) => { setVendors(Array.isArray(vendorData.vendors) ? vendorData.vendors : []); setOrders(Array.isArray(orderData.orders) ? orderData.orders : []) }).catch((error) => setMessage(error instanceof Error ? error.message : 'Could not load admin data.')) }, []); const update = (key: keyof typeof form) => (event: React.ChangeEvent<HTMLInputElement>) => setForm((current) => ({ ...current, [key]: event.target.value })); async function createVendor(event: FormEvent) { event.preventDefault(); try { const data = await api<{ issuedPin: string; vendor: Vendor }>('/api/admin/vendors', { method: 'POST', body: JSON.stringify(form) }); setVendors((current) => [...current, data.vendor]); setForm({ storeName: '', contactName: '', phone: '', address: '', city: '', state: '', zip: '', pin: '' }); setMessage(`${data.vendor.storeName} created. Vendor PIN: ${data.issuedPin}`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Vendor could not be created.') } } const bottles = orders.reduce((sum, order) => sum + Number(order.totalBottles || 0), 0); const value = orders.reduce((sum, order) => sum + Number(order.totalAmount || 0), 0); return <div className="admin-layout"><aside className="admin-nav"><img className="brand-logo" src={monstaLogo} alt="Monsta Squeeze" /><button className={tab === 'dashboard' ? 'active' : ''} onClick={() => setTab('dashboard')}>▦ <span>Dashboard</span></button><button className={tab === 'vendors' ? 'active' : ''} onClick={() => setTab('vendors')}>♙ <span>Vendor accounts</span></button><button className={tab === 'orders' ? 'active' : ''} onClick={() => setTab('orders')}>▤ <span>Orders</span></button><button className={tab === 'route' ? 'active' : ''} onClick={() => setTab('route')}>⌁ <span>Route / Delivery</span></button><button className={tab === 'analytics' ? 'active' : ''} onClick={() => setTab('analytics')}>◌ <span>Analytics</span></button><button onClick={onLogout}>↪ <span>Log out</span></button></aside><main className="admin-main"><header className="admin-header"><div><p className="eyebrow">Operations control</p><h1>{tab === 'dashboard' ? 'Dashboard' : tab === 'vendors' ? 'Vendor accounts' : tab === 'orders' ? 'Orders' : tab === 'route' ? 'Route / Delivery' : 'Analytics'}</h1><p className="muted">Manage retailers, PIN access, orders, and production readiness.</p></div><button className="text-button" onClick={onLogout}>Admin · Log out</button></header>{tab === 'dashboard' && <><div className="metric-grid"><div className="metric-card"><span>♧</span><small>Active vendors</small><strong>{vendors.filter((vendor) => vendor.status === 'ACTIVE').length}</strong></div><div className="metric-card"><span>▣</span><small>Open orders</small><strong>{orders.filter((order) => order.status === 'SUBMITTED').length}</strong></div><div className="metric-card"><span>◉</span><small>Bottles ordered</small><strong>{bottles}</strong></div><div className="metric-card"><span>$</span><small>Wholesale value</small><strong>${value.toFixed(0)}</strong></div></div><div className="admin-grid"><section className="admin-card"><div className="section-heading"><h2>Vendor accounts</h2><button className="small-button" onClick={() => setTab('vendors')}>Manage</button></div><p className="muted">{vendors.length} retailer accounts are stored in the interim system.</p></section><section className="admin-card"><div className="section-heading"><h2>Recent orders</h2><button className="small-button" onClick={() => setTab('orders')}>View all</button></div>{orders.slice(0, 4).map((order) => <div className="route-row" key={order.id}><span>{order.orderNumber}<small>{order.totalBottles} bottles</small></span><b>${Number(order.totalAmount || 0).toFixed(2)}</b><em>{order.status}</em></div>)}{!orders.length && <p className="muted">No submitted orders yet.</p>}</section></div></>}{tab === 'vendors' && <section className="admin-card"><div className="section-heading"><h2>Create vendor account</h2><span>Issue a PIN</span></div><form className="admin-vendor-form" onSubmit={createVendor}>{(['storeName', 'contactName', 'phone', 'address', 'city', 'state', 'zip', 'pin'] as const).map((key) => <label key={key}>{key === 'storeName' ? 'Store name' : key === 'contactName' ? 'Contact name' : key === 'pin' ? 'PIN (optional 4 digits)' : key.replace(/([A-Z])/g, ' $1')}<input required={key !== 'pin'} inputMode={key === 'pin' || key === 'zip' ? 'numeric' : undefined} maxLength={key === 'pin' ? 4 : undefined} value={form[key]} onChange={update(key)} /></label>)}<button className="primary-action" type="submit">Create account + issue PIN</button></form><p className="setup-note" role="status">{message}</p><div className="section-heading"><h2>Existing vendors</h2><span>{vendors.length}</span></div>{vendors.map((vendor) => <div className="route-row" key={vendor.id}><span>{vendor.storeName}<small>{vendor.vendorId} · {vendor.contactName}</small></span><b>{vendor.city}</b><em>{vendor.status}</em></div>)}</section>}{tab === 'orders' && <section className="admin-card"><div className="section-heading"><h2>Submitted orders</h2><span>{orders.length}</span></div>{orders.map((order) => <div className="route-row" key={order.id}><span>{order.orderNumber}<small>{vendors.find((vendor) => vendor.id === order.vendorId)?.storeName ?? 'Vendor'}</small></span><b>{order.totalBottles}</b><span>${Number(order.totalAmount || 0).toFixed(2)}</span><em>{order.status}</em></div>)}{!orders.length && <p className="muted">No orders submitted yet.</p>}</section>}{tab === 'route' && <section className="admin-card"><div className="section-heading"><h2>Route / delivery</h2><span>Ready orders</span></div>{orders.filter((order) => ['READY', 'OUT_FOR_DELIVERY'].includes(order.status)).map((order) => <div className="route-row" key={order.id}><span>{vendors.find((vendor) => vendor.id === order.vendorId)?.storeName ?? 'Vendor'}<small>{order.orderNumber}</small></span><b>{order.totalBottles}</b><span>{order.status}</span><em>Route</em></div>)}{!orders.some((order) => ['READY', 'OUT_FOR_DELIVERY'].includes(order.status)) && <p className="muted">No ready deliveries yet.</p>}</section>}{tab === 'analytics' && <section className="admin-card"><div className="section-heading"><h2>Analytics</h2><span>Stored portal data</span></div><div className="analytics-grid"><div><small>Total orders</small><strong>{orders.length}</strong></div><div><small>Bottles ordered</small><strong>{bottles}</strong></div><div><small>Wholesale value</small><strong>${value.toFixed(2)}</strong></div><div><small>Active vendors</small><strong>{vendors.length}</strong></div></div><p className="muted">Calculated from the interim Netlify Blobs data layer.</p></section>}</main></div> }

